public static int Run(string folder){var report=new Dictionary<string,object>();bool pass=false;try{var q=O(J.DeserializeObject(File.ReadAllText(Path.Combine(folder,"request.json"))));if(System.Diagnostics.Process.GetCurrentProcess().Id!=Convert.ToInt32(q["expected_pid"]))throw new Exception("Wrong host");dynamic legacy=Marshal.GetActiveObject("IronCAD.Application");var app=(IZBaseApp)legacy.ZIronCADApp;if(!app.ApiVersion.StartsWith("29."))throw new Exception("2027 required");string path=(string)q["output"];var doc=((Array)app.GetAllOpenDocs()).Cast<object>().Select(D).Single(d=>String.Equals(d.Name,path,StringComparison.OrdinalIgnoreCase));var s=(IZSceneDoc)doc;var u=(IZSceneDocUtility)s;report["initial_hood_suppressed"]=u.GetElementById(115).GetStateStatus(eZElementState.Z_SUPPRESSED);u.GetElementById(115).SetSuppressState(false);u.GetElementById(116).SetSuppressState(false);var ids=O(q["part_id_map"]);var original=(object[])q["inventory"];int physicalCount=CountParts(s.GetTopElement());if(physicalCount!=383)throw new Exception("Physical part count changed: "+physicalCount);report["physical_parts"]=physicalCount;double maxPose=0,maxSize=0;foreach(object rawPart in (object[])q["parts"]){var v=O(rawPart);int id=Convert.ToInt32(v["id"]);var part=(IZPart)u.GetElementById(ids.ContainsKey(id.ToString())?Convert.ToInt32(ids[id.ToString()]):id);var m=((IZSceneElement)part).GetTransformToGlobal();var old=((Array)v["world_matrix_m"]).Cast<object>().Select(Convert.ToDouble).ToArray();var b=((Array)part.GetBody(true).GetBoundingBox()).Cast<object>().Select(Convert.ToDouble).ToArray();var oldb=((Array)v["bounds_m"]).Cast<object>().Select(Convert.ToDouble).ToArray();for(int k=0;k<16;k++)maxPose=Math.Max(maxPose,Math.Abs(m.GetValue(k/4,k%4)-old[k])*1000);for(int k=0;k<6;k++)maxSize=Math.Max(maxSize,Math.Abs(b[k]-oldb[k])*1000);}report["max_final_pose_error_mm"]=maxPose;report["max_final_size_error_mm"]=maxSize;if(maxPose>.08||maxSize>.08)throw new Exception("Final baseline geometry changed");var cuts=new List<object>();
foreach(object raw in (object[])q["cut_replacements"]){var p=O(raw);int originalPart=Convert.ToInt32(p["target_part"]);int nativePart=Convert.ToInt32(ids[originalPart.ToString()]);var originalRow=original.Select(O).Single(x=>Convert.ToInt32(x["id"])==originalPart);var originalFeatures=((object[])originalRow["features"]).Select(O).ToArray();int index=Array.FindIndex(originalFeatures,x=>x.ContainsKey("id")&&Convert.ToInt32(x["id"])==Convert.ToInt32(p["cut_id"]));var feature=((IZPartFeatureMgr)u.GetElementById(nativePart)).GetFeatureAt(index);var target=(IZExtrudeFeature)feature;var tool=(IZExtrudeFeature)Find((IZPartFeatureMgr)u.GetElementById(Convert.ToInt32(p["tool_part"])),Convert.ToInt32(p["tool_feature"]));var tm=((IZSceneElement)target.CrossSection).GetTransformToGlobal();var sm=((IZSceneElement)tool.CrossSection).GetTransformToGlobal();double matrixError=Enumerable.Range(0,16).Max(k=>Math.Abs(tm.GetValue(k/4,k%4)-sm.GetValue(k/4,k%4)));var a=Lengths(target.CrossSection);var b=Lengths(tool.CrossSection);double curveError=a.Length==b.Length?Enumerable.Range(0,a.Length).Max(k=>Math.Abs(a[k]-b[k])):1;bool ok=matrixError<1e-7&&curveError<1e-7&&feature.OperationType==eZOperationType.Z_SUBTRACT&&!((IZElement)feature).GetStateStatus(eZElementState.Z_SUPPRESSED);cuts.Add(new{source_cut_id=p["cut_id"],native_cut_id=((IZElement)feature).Id,target_part=nativePart,tool_part=p["tool_part"],matrix_error=matrixError,curve_error_m=curveError,curves=a.Length,passed=ok});if(!ok)throw new Exception("Cut differs from hardware mounting tool: "+p["cut_id"]);}
report["cuts"]=cuts;
var visibility=new List<object>();foreach(int id in new[]{115,116}){var e=u.GetElementById(id);visibility.Add(new{id=id,was_suppressed=e.GetStateStatus(eZElementState.Z_SUPPRESSED),was_hidden=e.GetStateStatus(eZElementState.Z_HIDDEN)});e.SetSuppressState(false);e.SetDisplayFlag(true);}report["visibility_before"]=visibility;
var names=new Dictionary<int,string>{{179,"Czapka — przód"},{183,"Czapka — prawa ściana"},{187,"Czapka — lewa ściana"},{191,"Czapka — tył"},{195,"Czapka — dach"},{200,"Korpus — przód"},{204,"Korpus — prawa ściana"},{208,"Korpus — lewa ściana"},{212,"Korpus — tył"},{216,"Korpus — dno"}};foreach(var pair in names)u.GetElementById(Convert.ToInt32(ids[pair.Key.ToString()])).Name="RockPro | Sklejka — "+pair.Value;
u.GetElementById(115).Name="RockPro | Czapka zdejmowana";u.GetElementById(116).Name="RockPro | Korpus dolny";var revealStates=new List<object>();Reveal(u.GetElementById(115),revealStates);report["hood_states_before_reveal"]=revealStates;s.Update();s.SelectionMgr.RemoveAllFromSelection();s.SelectionMgr.AddElementToSelection(u.GetElementById(115),false);u.ShowSelectedAndSubItem();s.SelectionMgr.RemoveAllFromSelection();s.Redraw();var camera=(IZCamera)s.CameraMgr.ActiveCamera;camera.Perspective=false;camera.Direction=new double[]{0,1,0};camera.Up=new double[]{0,0,1};s.AdjustCameraToFitShapeInRect(1800,1100);s.Redraw();s.ExportImage(Path.Combine(folder,"wyciecia-przod.png"),eZImageFormat.Z_IMAGE_PNG,1800,1100,true);camera.Direction=new double[]{.45,.8,-.5};s.AdjustCameraToFitShapeInRect(1400,1100);s.Redraw();s.ExportImage(Path.Combine(folder,"final.png"),eZImageFormat.Z_IMAGE_PNG,1400,1100,true);s.SaveAs(path,eZLinksSaveOptions.Z_LINKS_COPY_ALL,false);pass=true;
}catch(Exception ex){report["error"]=ex.ToString();}report["passed"]=pass;File.WriteAllText(Path.Combine(folder,"result.json"),J.Serialize(report));return pass?0:1;}
